var n = app.alert("Choose filename:\n\nYes = _n1\n\nNo = _o1\n\nCancel = Type custom name", 3, 3, "Save As");
var f = "";

if (n === 4) {
    f = "_n1";
} else if (n === 3) {
    f = "_o1";
} else if (n === 2) {
    f = app.response("Enter file name:", "Save As", "_n1");
}

if (f) {
    this.saveAs("/c/jo/diff/" + f + ".pdf");
    app.alert(f + ".pdf Saved!", 3);
}
